-- Generated by hyprmoncfg

-- hyprmoncfg owns monitor configuration, so Omarchy's display panel settings stand down.
omarchy_monitor_panel_settings = false

hl.monitor({
  output = "desc:Samsung Electric Company SAMSUNG 0x01000000",
  mode = "3840x2160@30.00",
  position = "0x0",
  scale = 2,
  vrr = 0,
  bitdepth = 10,
  sdr_min_luminance = 0.2,
  sdr_max_luminance = 80,
})

hl.monitor({
  output = "desc:Dell Inc. DELL U2419H HWCDKS2",
  disabled = true,
})

hl.monitor({
  output = "desc:LG Display 0x05A2",
  disabled = true,
})

-- Omarchy leaves GDK_SCALE to this file.
if type(o) == "table" then hl.env("GDK_SCALE", "2") end

-- Omarchy's Mirror Display toggle takes effect over the profile while it is on.
do
  local state = os.getenv("XDG_STATE_HOME") or (os.getenv("HOME") .. "/.local/state")
  local path = state .. "/omarchy/toggles/hypr/internal-monitor-mirror.lua"
  local file = io.open(path, "r")
  if type(o) == "table" and file then
    file:close()
    dofile(path)
  elseif file then
    file:close()
  end
end
